function QRScanner({onClose,token}){const [scan,setScan]=useState(0);useEffect(()=>{const i=setInterval(()=>setScan(x=>Math.min(100,x+8)),150);return()=>clearInterval(i)},[]);return <div className="modal"><div className="scanner-card"><button className="modal-close" onClick={onClose}><XCircle/></button><div className="scanner-head"><ScanLine/><div><b>QR Verification</b><small>Point the camera at a QueueLess pass</small></div></div><div className="scan-frame"><div className="corner c1"></div><div className="corner c2"></div><div className="corner c3"></div><div className="corner c4"></div><div className="scan-line" style={{top:`${Math.min(88,10+scan*.78)}%`}}></div><div className="scan-qr"><QRCodeSVG value={token?.qrPayload||'DEMO-QR'} size={135}/></div></div><div className="scan-status">{scan<100?<><span className="spinner"></span>Analyzing token signature… {scan}%</>:<><CheckCircle2/> Verified • {token?.token||'DEMO'}</>}</div></div></div>}
